.css","sourcesContent":[".page-title .title {\n  font-size: 16px;\n  color: #4060a4;\n  text-transform: uppercase;\n  margin: 0;\n  padding-top: 2rem;\n  padding-bottom: 0.5rem; }\n\n.page-title .sub-title {\n  font-size: 1.2rem; }\n\n.page-results {\n  margin: 1.5rem 1.5rem 0; }\n\n.page-form {\n  margin: 1.5rem 1.5rem 0;\n  padding-top: 1rem;\n  padding-bottom: 1rem;\n  background: #fff;\n  box-shadow: 0 2px 2px 0 rgba(0, 0, 0, 0.14), 0 3px 1px -2px rgba(0, 0, 0, 0.2), 0 1px 5px 0 rgba(0, 0, 0, 0.12); }\n  .page-form .row {\n    margin-bottom: 0; }\n    .page-form .row .col {\n      padding: 0 1.5rem; }\n  .page-form .input-field {\n    font-size: 1.2rem; }\n    .page-form .input-field label {\n      left: 1.5rem;\n      font-size: 1.1rem;\n      color: #808080; }\n    .page-form .input-field input[type=text] {\n      height: 3.5rem;\n      line-height: 3.5rem;\n      border-color: #ccc;\n      font-size: 1.2rem;\n      color: #2c2c2c;\n      margin-bottom: 10px; }\n      .page-form .input-field input[type=text][readonly=\"readonly\"] {\n        border-bottom: 1px solid #ccc; }\n        .page-form .input-field input[type=text][readonly=\"readonly\"] + label {\n          color: #808080; }\n      .page-form .input-field input[type=text]:focus:not([readonly]) {\n        border-color: #549cba; }\n        .page-form .input-field input[type=text]:focus:not([readonly]) + label {\n          color: #549cba; }\n    .page-form .input-field ::-webkit-input-placeholder {\n      /* Chrome/Opera/Safari */\n      color: #2c2c2c; }\n    .page-form .input-field .icon-calendar {\n      position: absolute;\n      right: 15px;\n      top: 10px;\n      font-size: 16px;\n      color: #4d6273; }\n  .page-form .dropdown-content {\n    margin-top: 5px;\n    max-height: 400px; }\n  .page-form .dropdown-content li > a, .page-form .dropdown-content li > span {\n    font-size: 1.2rem;\n    color: #2c2c2c; }\n  .page-form .select-wrapper {\n    /*span.caret {\r\n            color: $blue-light;\r\n        }*/ }\n    .page-form .select-wrapper input.select-dropdown {\n      height: 3.5rem;\n      line-height: 3.5rem;\n      border-color: #ccc;\n      font-size: 1.2rem;\n      color: #2c2c2c;\n      margin-bottom: 10px; }\n    .page-form .select-wrapper span.caret {\n      font-family: 'icomoon' !important;\n      color: transparent; }\n      .page-form .select-wrapper span.caret:before {\n        content: \"\\e916\";\n        color: #4d6273;\n        font-size: 18px;\n        position: absolute;\n        top: -7px;\n        right: -5px; }\n\n.table-title {\n  background: #8aa4b8;\n  padding: 4px 15px;\n  color: #fff;\n  text-transform: uppercase; }\n\n.panel-heading {\n  background: #4C6375;\n  border-radius: 0;\n  padding: 0; }\n  .panel-heading .panel-title {\n    color: #fff;\n    padding: 5px 15px;\n    font-size: 13px; }\n    .panel-heading .panel-title .icon-arrow {\n      margin: 0;\n      font-size: 13px;\n      transform: rotate(-90deg);\n      transition: 0.3s ease all; }\n    .panel-heading .panel-title:hover, .panel-heading .panel-title:active, .panel-heading .panel-title:focus {\n      color: #fff; }\n  .panel-heading + .panel-collapse > .panel-body {\n    border-top: none !important; }\n  .panel-heading.active .panel-title .icon-arrow {\n    transform: rotate(0); }\n\n.table {\n  table-layout: fixed; }\n\n.no-info-row {\n  text-align: center;\n  border: 1px solid #ccc;\n  padding: 5px; }\n\n\n\n/** WEBPACK FOOTER **\n ** webpack:///www/css/source/pages/common.scss\n **/",".flat-popup {\n  background: #fff;\n  box-shadow: 0 0 10px #ccc;\n  float: left;\n  left: 50%;\n  position: absolute;\n  top: 100px;\n  z-index: 99999;\n  -webkit-background-clip: padding-box;\n  /* for Safari */\n  background-clip: padding-box;\n  /* for IE9+, Firefox 4+, Opera, Chrome */ }\n  .flat-popup .title-bar {\n    background-color: #4C6375;\n    padding: 7px 20px;\n    position: relative; }\n    .flat-popup .title-bar .txt-title {\n      color: #fff;\n      font-siz