Y,EAAE","file":"www/css/build/pages/reports/livereport.css","sourcesContent":[".page-title .title {\n  font-size: 16px;\n  color: #4060a4;\n  text-transform: uppercase;\n  margin: 0;\n  padding-top: 2rem;\n  padding-bottom: 0.5rem; }\n\n.page-title .sub-title {\n  font-size: 1.2rem; }\n\n.page-results {\n  margin: 1.5rem 1.5rem 0; }\n\n.page-form {\n  margin: 1.5rem 1.5rem 0;\n  padding-top: 1rem;\n  padding-bottom: 1rem;\n  background: #fff;\n  box-shadow: 0 2px 2px 0 rgba(0, 0, 0, 0.14), 0 3px 1px -2px rgba(0, 0, 0, 0.2), 0 1px 5px 0 rgba(0, 0, 0, 0.12); }\n  .page-form .row {\n    margin-bottom: 0; }\n    .page-form .row .col {\n      padding: 0 1.5rem; }\n  .page-form .input-field {\n    font-size: 1.2rem; }\n    .page-form .input-field label {\n      left: 1.5rem;\n      font-size: 1.1rem;\n      color: #808080; }\n    .page-form .input-field input[type=text] {\n      height: 3.5rem;\n      line-height: 3.5rem;\n      border-color: #ccc;\n      font-size: 1.2rem;\n      color: #2c2c2c;\n      margin-bottom: 10px; }\n      .page-form .input-field input[type=text][readonly=\"readonly\"] {\n        border-bottom: 1px solid #ccc; }\n        .page-form .input-field input[type=text][readonly=\"readonly\"] + label {\n          color: #808080; }\n      .page-form .input-field input[type=text]:focus:not([readonly]) {\n        border-color: #549cba; }\n        .page-form .input-field input[type=text]:focus:not([readonly]) + label {\n          color: #549cba; }\n    .page-form .input-field ::-webkit-input-placeholder {\n      /* Chrome/Opera/Safari */\n      color: #2c2c2c; }\n    .page-form .input-field .icon-calendar {\n      position: absolute;\n      right: 15px;\n      top: 10px;\n      font-size: 16px;\n      color: #4d6273; }\n  .page-form .dropdown-content {\n    margin-top: 5px;\n    max-height: 400px; }\n  .page-form .dropdown-content li > a, .page-form .dropdown-content li > span {\n    font-size: 1.2rem;\n    color: #2c2c2c; }\n  .page-form .select-wrapper {\n    /*span.caret {\r\n            color: $blue-light;\r\n        }*/ }\n    .page-form .select-wrapper input.select-dropdown {\n      height: 3.5rem;\n      line-height: 3.5rem;\n      border-color: #ccc;\n      font-size: 1.2rem;\n      color: #2c2c2c;\n      margin-bottom: 10px; }\n    .page-form .select-wrapper span.caret {\n      font-family: 'icomoon' !important;\n      color: transparent; }\n      .page-form .select-wrapper span.caret:before {\n        content: \"\\e916\";\n        color: #4d6273;\n        font-size: 18px;\n        position: absolute;\n        top: -7px;\n        right: -5px; }\n\n.table-title {\n  background: #8aa4b8;\n  padding: 4px 15px;\n  color: #fff;\n  text-transform: uppercase; }\n\n.panel-heading {\n  background: #4C6375;\n  border-radius: 0;\n  padding: 0; }\n  .panel-heading .panel-title {\n    color: #fff;\n    padding: 5px 15px;\n    font-size: 13px; }\n    .panel-heading .panel-title .icon-arrow {\n      margin: 0;\n      font-size: 13px;\n      transform: rotate(-90deg);\n      transition: 0.3s ease all; }\n    .panel-heading .panel-title:hover, .panel-heading .panel-title:active, .panel-heading .panel-title:focus {\n      color: #fff; }\n  .panel-heading + .panel-collapse > .panel-body {\n    border-top: none !important; }\n  .panel-heading.active .panel-title .icon-arrow {\n    transform: rotate(0); }\n\n.table {\n  table-layout: fixed; }\n\n.no-info-row {\n  text-align: center;\n  border: 1px solid #ccc;\n  padding: 5px; }\n\n\n\n/** WEBPACK FOOTER **\n ** webpack:///www/css/source/pages/common.scss\n **/",".page-form .input-field input[type=radio] + label {\n  left: 0;\n  padding-right: 10px;\n  padding-left: 25px; }\n\n.page-form input[type=\"radio\"] + label {\n  margin: 0 0 10px 0; }\n\n.page-form .date-range {\n  min-width: 200px; }\n\n.page-form .button-block .btn {\n  margin-bottom: 10px; }\n\n@media only screen and (min-width: 993px) {\n  .page-form .button-block {\n    width: 10% !important; } }\n\n.page-results .result-content {\n  box-shadow: none;\n  border: 0;\n  margin: 0.5rem 0 1rem 0; }\n\n.multiselect-container {\n  min-width: 250px; }\n  .multiselect-container > label {\n    position: absolute;\n    top: -14px; }\n  .multiselect-container > a.ui-multiselect {\n    height: 3.5rem;\n    line-height: 3.5rem;\n    border: none;\n    border-bottom: 1px solid #ccc;\n    cursor: pointer;\n    position: relative;\n    border-radius: 0;\n    width: 100% !important;\n    margin: 0 0 10px 0; }\n    .multiselect-container > a.ui-multiselect > input {\n      width: 100% !important;\n      height: 100% !important;\n      cursor: pointer; }\n    .multiselect-container > a.ui-multiselect .ui-multiselect-icon {\n      font-family: 'icomoon' !important; }\n      .multiselect-container > a.ui-multiselect .ui-multiselect-icon:before {\n        content: \"\\E916\";\n        color: #282d38;\n        font-size: 18px;\n        position: absolute;\n        top: 14px;\n        right: -5px;\n        line-height: 1; }\n\n.breadCrumbHolder {\n  display: none; }\n  .breadCrumbHolder .level {\n    display: none; }\n\n.breadcrumb {\n  text-align: center;\n  display: inline-block;\n  overflow: hidden; }\n  .breadcrumb > a {\n    text-decoration: none;\n    outline: none;\n    display: block;\n    float: left;\n    font-size: 12px;\n    line-height: 30px;\n    color: #fff;\n    padding: 0 10px 0 25px;\n    position: relative; }\n    .breadcrumb > a:first-child {\n      padding-left: 10px; }\n      .breadcrumb > a:first-child::before {\n        left: 14px; }\n    .breadcrumb > a:last-child {\n      padding-right: 20px; }\n      .breadcrumb > a:last-child::after {\n        content: none; }\n    .breadcrumb > a::after {\n      content: '';\n      position: absolute;\n      top: 0;\n      right: -16px;\n      width: 30px;\n      height: 30px;\n      transform: scale(0.8) rotate(45deg);\n      z-index: 1;\n      border-right: 3px solid #ca1e58;\n      border-top: 3px solid #ca1e58;\n      border-radius: 0 5px 0 50px; }\n  .breadcrumb.flat a, .breadcrumb.flat a::after {\n    background: #fff;\n    color: #4C6375; }\n  .breadcrumb.flat a::before {\n    background: #fff;\n    box-shadow: 0 0 0 1px #ec407a; }\n  .breadcrumb.flat a:hover, .breadcrumb.flat a.active {\n    color: #fff; }\n    .breadcrumb.flat a:hover, .breadcrumb.flat a:hover::after, .breadcrumb.flat a.active, .breadcrumb.flat a.active::after {\n      background: #4C6375; }\n    .breadcrumb.flat a:hover::before, .breadcrumb.flat a.active::before {\n      color: #4C6375; }\n  .breadcrumb.flat a.active:hover {\n    background: #4C6375; }\n\n.calendar .icon-calendar {\n  color: #4c6375;\n  font-size: 17px;\n  cursor: pointer; }\n\n.negative-number, .positive-number {\n  color: #ff0000; }\n\n.highlight, .table > tbody > tr > td.highlight {\n  background-color: #F8F1A0; }\n\n.select-wrapper input.select-dropdown {\n  font-size: 13px; }\n\n.select-wrapper span.caret {\n  font-family: 'icomoon' !important;\n  color: transparent !important; }\n  .select-wrapper span.caret:before {\n    content: \"\\E916\";\n    color: #282d38;\n    font-size: 18px;\n    position: absolute;\n    top: -6px;\n    right: -5px; }\n\n.input-field input[type=\"radio\"] + label {\n  padding-left: 20px !important; }\n\n[type=\"radio\"] + label:before, [type=\"radio\"] + label:after {\n  margin: 4px 0; }\n\n[type=\"radio\"].with-gap:checked + label:before, [type=\"radio\"].with-gap:checked + label:after {\n  border-color: #6790b0; }\n\n[type=\"radio\"]:not(:checked) + label:before, [type=\"radio\"]:not(:checked) + label:after {\n  border-color: #6790b0; }\n\n[type=\"radio\"].with-gap:checked + label:after {\n  background-color: #6790b0; }\n\n\n\n/** WEBPACK FOOTER **\n ** webpack:///www/css/source/extensions/report-ex.scss\n **/",".popup-block-body {\n  background: transparent;\n  border: none;\n  background-color: #ffffff;\n  position: fixed;\n  opacity: 0.7;\n  filter: alpha(opacity=70);\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100