ht: 30px;\n      transform: scale(0.8) rotate(45deg);\n      z-index: 1;\n      border-right: 3px solid #ca1e58;\n      border-top: 3px solid #ca1e58;\n      border-radius: 0 5px 0 50px; }\n  .breadcrumb.flat a, .breadcrumb.flat a::after {\n    background: #fff;\n    color: #4C6375; }\n  .breadcrumb.flat a::before {\n    background: #fff;\n    box-shadow: 0 0 0 1px #ec407a; }\n  .breadcrumb.flat a:hover, .breadcrumb.flat a.active {\n    color: #fff; }\n    .breadcrumb.flat a:hover, .breadcrumb.flat a:hover::after, .breadcrumb.flat a.active, .breadcrumb.flat a.active::after {\n      background: #4C6375; }\n    .breadcrumb.flat a:hover::before, .breadcrumb.flat a.active::before {\n      color: #4C6375; }\n  .breadcrumb.flat a.active:hover {\n    background: #4C6375; }\n\n.calendar .icon-calendar {\n  color: #4c6375;\n  font-size: 17px;\n  cursor: pointer; }\n\n.negative-number, .positive-number {\n  color: #ff0000; }\n\n.highlight, .table > tbody > tr > td.highlight {\n  background-color: #F8F1A0; }\n\n.select-wrapper input.select-dropdown {\n  font-size: 13px; }\n\n.select-wrapper span.caret {\n  font-family: 'icomoon' !important;\n  color: transparent !important; }\n  .select-wrapper span.caret:before {\n    content: \"\\E916\";\n    color: #282d38;\n    font-size: 18px;\n    position: absolute;\n    top: -6px;\n    right: -5px; }\n\n.input-field input[type=\"radio\"] + label {\n  padding-left: 20px !important; }\n\n[type=\"radio\"] + label:before, [type=\"radio\"] + label:after {\n  margin: 4px 0; }\n\n[type=\"radio\"].with-gap:checked + label:before, [type=\"radio\"].with-gap:checked + label:after {\n  border-color: #6790b0; }\n\n[type=\"radio\"]:not(:checked) + label:before, [type=\"radio\"]:not(:checked) + label:after {\n  border-color: #6790b0; }\n\n[type=\"radio\"].with-gap:checked + label:after {\n  background-color: #6790b0; }\n\n.col-small {\n  width: 5%; }\n\n.col-extra-small {\n  width: 2%; }\n\n.col-medium {\n  width: 15%; }\n\n.col-large {\n  width: 40%; }\n\n.col-child {\n  width: 10%; }\n  .col-child.small {\n    width: 7%; }\n\n#UserGuidePopup ul li {\n  list-style-type: disc; }\n  #UserGuidePopup ul li ul li {\n    list-style-type: circle; }\n\n\n\n/** WEBPACK FOOTER **\n ** webpack:///www/css/source/extensions/report-ex.scss\n **/",".popup-block-body {\n  background: transparent;\n  border: none;\n  background-color: #ffffff;\n  position: fixed;\n  opacity: 0.7;\n  filter: alpha(opacity=70);\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  z-index: 10000; }\n\n.flat-popup {\n  background: #fff;\n  box-shadow: 0 0 10px #ccc;\n  position: absolute;\n  z-index: 99999;\n  -webkit-background-clip: padding-box;\n  /* for Safari */\n  background-clip: padding-box;\n  /* for IE9+, Firefox 4+, Opera, Chrome */ }\n  .flat-popup .title-bar {\n    background-color: #4C6375;\n    padding: 7px 20px;\n    position: relative; }\n    .flat-popup .title-bar .txt-title {\n      color: #fff;\n      font-size: 12px;\n      font-weight: bold; }\n    .flat-popup .title-bar .popup-close {\n      color: #fff;\n      display: block;\n      height: 10px;\n      width: 10px;\n      position: absolute;\n      right: 10px;\n      top: 8px; }\n  .flat-popup .wrapContent {\n    overflow-y: auto; }\n    .flat-popup .wrapContent h1, .flat-popup .wrapContent h2, .flat-popup .wrapContent h3, .flat-popup .wrapContent h4, .flat-popup .wrapContent h5, .flat-popup .wrapContent h6 {\n      font-weight: bold; }\n    .flat-popup .wrapContent .rule {\n      padding: 8px 10px; }\n      .flat-popup .wrapContent .rule ul, .flat-popup .wrapContent .rule div {\n        color: #515151;\n        font-size: 12px;\n        line-height: 20px;\n        margin: 0;\n        padding-left: 15px; }\n      .flat-popup .wrapContent .rule h4 {\n        color: #515151;\n        font-size: 12px;\n        margin: 0 0 5px; }\n      .flat-popup .wrapContent .rule .newline {\n        padding-top: 12px; }\n      .flat-popup .wrapContent .rule:last-child {\n        border-bottom: medium none; }\n    .flat-popup .wrapContent .line {\n      border: none;\n      overflow: auto;\n      width: auto;\n      background-color: #ebeaea;\n      height: 1px;\n      margin: 0 10px; }\n\n\n\n/** WEBPACK FOOTER **\n ** webpack:///www/css/source/components/flatpopup/flatpopup.scss\n **/",".daterangepicker {\r\n  position: absolute;\r\n  color: inherit;\r\n  background: #fff;\r\n  border-radius: 4px;\r\n  width: 278px;\r\n  padding: 4px;\r\n  margin-top: 1px;\r\n  top: 100px;\r\n  left: 20px;\r\n  /* Calendars */ }\r\n  .daterangepicker:before, .daterangepicker:after {\r\n    position: absolute;\r\n    display: inline-block;\r\n    border-bottom-color: rgba(0, 0, 0, 0.2);\r\n    content: ''; }\r\n  .daterangepicker:before {\r\n    top: -7px;\r\n    border-right: 7px solid transparent;\r\n    border-left: 7px solid transparent;\r\n    border-bottom: 7px solid #ccc; }\r\n  .daterangepicker:after {\r\n    top: -6px;\r\n    border-right: 6px solid transparent;\r\n    border-bottom: 6px solid #fff;\r\n    border-left: 6px solid transparent; }\r\n  .daterangepicker.opensleft:before {\r\n    right: 9px; }\r\n  .daterangepicker.opensleft:after {\r\n    right: 10px; }\r\n  .daterangepicker.openscenter:before {\r\n    left: 0;\r\n    right: 0;\r\n    width: 0;\r\n    margin-left: auto;\r\n    margin-right: auto; }\r\n  .daterangepicker.openscenter:after {\r\n    left: 0;\r\n    right: 0;\r\n    width: 0;\r\n    margin-left: auto;\r\n    margin-right: auto; }\r\n  .daterangepicker.opensright:before {\r\n    left: 9px; }\r\n  .daterangepicker.opensright:after {\r\n    left: 10px; }\r\n  .daterangepicker.dropup {\r\n    margin-top: -5px; }\r\n    .daterangepicker.dropup:before {\r\n      top: initial;\r\n      bottom: -7px;\r\n      border-bottom: initial;\r\n      border-top: 7px solid #ccc; }\r\n    .daterangepicker.dropup:after {\r\n      top: initial;\r\n      bottom: -6px;\r\n      border-bottom: initial;\r\n      border-top: 6px solid #fff; }\r\n  .dat