e {\n  min-width: 200px; }\n\n.page-form .button-block .btn {\n  margin-bottom: 10px; }\n\n@media only screen and (min-width: 993px) {\n  .page-form .button-block {\n    width: 10% !important; } }\n\n.page-results .result-content {\n  box-shadow: none;\n  border: 0;\n  margin: 0.5rem 0 1rem 0; }\n\n.multiselect-container {\n  min-width: 250px; }\n  .multiselect-container > label {\n    position: absolute;\n    top: -14px; }\n  .multiselect-container > a.ui-multiselect {\n    height: 3.5rem;\n    line-height: 3.5rem;\n    border: none;\n    border-bottom: 1px solid #ccc;\n    cursor: pointer;\n    position: relative;\n    border-radius: 0;\n    width: 100% !important;\n    margin: 0 0 10px 0; }\n    .multiselect-container > a.ui-multiselect > input {\n      width: 100% !important;\n      height: 100% !important;\n      cursor: pointer; }\n    .multiselect-container > a.ui-multiselect .ui-multiselect-icon {\n      font-family: 'icomoon' !important; }\n      .multiselect-container > a.ui-multiselect .ui-multiselect-icon:before {\n        content: \"\\E916\";\n        color: #282d38;\n        font-size: 18px;\n        position: absolute;\n        top: 14px;\n        right: -5px;\n        line-height: 1; }\n\n.breadCrumbHolder {\n  display: none; }\n  .breadCrumbHolder .level {\n    display: none; }\n\n.breadcrumb {\n  text-align: center;\n  display: inline-block;\n  overflow: hidden; }\n  .breadcrumb > a {\n    text-decoration: none;\n    outline: none;\n    display: block;\n    float: left;\n    font-size: 12px;\n    line-height: 30px;\n    color: #fff;\n    padding: 0 10px 0 25px;\n    position: relative; }\n    .breadcrumb > a:first-child {\n      padding-left: 10px; }\n      .breadcrumb > a:first-child::before {\n        left: 14px; }\n    .breadcrumb > a:last-child {\n      padding-right: 20px; }\n      .breadcrumb > a:last-child::after {\n        content: none; }\n    .breadcrumb > a::after {\n      content: '';\n      position: absolute;\n      top: 0;\n      right: -16px;\n      width: 30px;\n      height: 30px;\n      transform: scale(0.8) rotate(45deg);\n      z-index: 1;\n      border-right: 3px solid #ca1e58;\n      border-top: 3px solid #ca1e58;\n      border-radius: 0 5px 0 50px; }\n  .breadcrumb.flat a, .breadcrumb.flat a::after {\n    background: #fff;\n    color: #4C6375; }\n  .breadcrumb.flat a::before {\n    background: #fff;\n    box-shadow: 0 0 0 1px #ec407a; }\n  .breadcrumb.flat a:hover, .breadcrumb.flat a.active {\n    color: #fff; }\n    .breadcrumb.flat a:hover, .breadcrumb.flat a:hover::after, .breadcrumb.flat a.active, .breadcrumb.flat a.active::after {\n      background: #4C6375; }\n    .breadcrumb.flat a:hover::before, .breadcrumb.flat a.active::before {\n      color: #4C6375; }\n  .breadcrumb.flat a.active:hover {\n    background: #4C6375; }\n\n.calendar .icon-calendar {\n  color: #4c6375;\n  font-size: 17px;\n  cursor: pointer; }\n\n.negative-number, .positive-number {\n  color: #ff0000; }\n\n.highlight, .table > tbody > tr > td.highlight {\n  background-color: #F8F1A0; }\n\n.select-wrapper input.select-dropdown {\n  font-size: 13px; }\n\n.select-wrapper span.caret {\n  font-family: 'icomoon' !important;\n  color: transparent !important; }\n  .select-wrapper span.caret:before {\n    content: \"\\E916\";\n    color: #282d38;\n    font-size: 18px;\n    position: absolute;\n    top: -6px;\n    right: -5px; }\n\n.input-field input[type=\"radio\"] + label {\n  padding-left: 20px !important; }\n\n[type=\"radio\"] + label:before, [type=\"radio\"] + label:after {\n  margin: 4px 0; }\n\n[type=\"radio\"].with-gap:checked + label:before, [type=\"radio\"].with-gap:checked + label:after {\n  border-color: #6790b0; }\n\n[type=\"radio\"]:not(:checked) + label:before, [type=\"radio\"]:not(:checked) + label:after {\n  border-color: #6790b0; }\n\n[type=\"radio\"].with-gap:checked + label:after {\n  background-color: #6790b0; }\n\n.col-small {\n  width: 5%; }\n\n.col-extra-small {\n  width: 2%; }\n\n.col-medium {\n  width: 15%; }\n  .col-medium.small {\n    width: 10%; }\n\n.col-large {\n  width: 40%; }\n  .col-large.small {\n    width: 35%; }\n\n.col-child {\n  width: 10%; }\n  .col-child.small {\n    width: 6%; }\n\n#UserGuidePopup ul li {\n  list-style-type: disc; }\n  #UserGuidePopup ul li ul li {\n    list-style-type: circle; }\n\n\n\n/** WEBPACK FOOTER **\n ** webpack:///www/css/source/extensions/report-ex.scss\n **/",".popup-block-body {\n  background: transparent;\n  border: none;\n  background-color: #ffffff;\n  position: fixed;\n  opacity: 0.7;\n  filter: alpha(opacity=70);\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  z-index: 10000; }\n\n.flat-popup {\n  background: #fff;\n  box-shadow: 0 0 10px #ccc;\n  position: absolute;\n  z-index: 99999;\n  -webkit-background-clip: padding-box;\n  /* for Safari */\n  background-clip: padding-box;\n  /* for IE9+, Firefox 4+, Opera, Chrome */ }\n  .flat-popup .title-bar {\n    background-color: #4C6375;\n    padding: 7px 20px;\n    position: relative; }\n    .flat-popup .title-bar .txt-title {\n      color: #fff;\n      font-size: 12px;\n      font-weight: bold; }\n    .flat-popup .title-bar .popup-close {\n      color: #fff;\n      display: block;\n      height: 10px;\n      width: 10px;\n      position: absolute;\n      right: 10px;\n      top: 8px; }\n  .flat-popup .wrapContent {\n    overflow-y: auto; }\n    .flat-popup .wrapContent h1, .flat-popup .wrapContent h2, .flat-popup .wrapContent h3, .flat-popup .wrapContent h4, .flat-popup .wrapContent h5, .flat-popup .wrapContent h6 {\n      font-weight: bold; }\n    .flat-popup .wrapContent .rule {\n      padding: 8px 10px; }\n      .flat-popup .wrapContent .rule ul, .flat-popup .wrapContent .rule div {\n        color: #515151;\n        font-size: 12px;\n        line-height: 20px;\n        margin: 0;\n        padding-left: 15px; }\n      .flat-popup .wrapContent .rule h4 {\n        color: #515151;\n        font-size: 12px;\n        margin: 0 0 5px; }\n      .flat-popu